import java.util.*;

class NaivePath {
    private final List<List<Integer>> adj;
    private final int[] parent, depth;
    private final long[] val;

    NaivePath(int n, int root, int[][] edges, long[] values) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        parent = new int[n];
        depth = new int[n];
        val = values.clone();
        Deque<int[]> st = new ArrayDeque<>();
        boolean[] seen = new boolean[n];
        st.push(new int[]{root, root, 0});
        while (!st.isEmpty()) {
            int[] c = st.pop();
            if (seen[c[0]]) continue;
            seen[c[0]] = true; parent[c[0]] = c[1]; depth[c[0]] = c[2];
            for (int nx : adj.get(c[0])) if (!seen[nx]) st.push(new int[]{nx, c[0], c[2] + 1});
        }
    }

    void update(int node, long v) { val[node] = v; }

    long pathQuery(int u, int v) {
        long sum = 0;
        while (depth[u] > depth[v]) { sum += val[u]; u = parent[u]; }
        while (depth[v] > depth[u]) { sum += val[v]; v = parent[v]; }
        while (u != v) { sum += val[u] + val[v]; u = parent[u]; v = parent[v]; }
        sum += val[u];   // the LCA, counted once
        return sum;
    }
}

