from collections import defaultdict

class NaivePath:
    def __init__(self, n: int, root: int, edges: list[tuple[int, int]], values: list[int]) -> None:
        adj = defaultdict(list)
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        self.parent = [root] * n
        self.depth = [0] * n
        self.val = list(values)
        seen = [False] * n
        stack = [(root, root, 0)]
        while stack:
            node, par, dep = stack.pop()
            if seen[node]:
                continue
            seen[node] = True
            self.parent[node] = par
            self.depth[node] = dep
            for nxt in adj[node]:
                if not seen[nxt]:
                    stack.append((nxt, node, dep + 1))

    def update(self, node: int, v: int) -> None:
        self.val[node] = v

    def path_query(self, u: int, v: int) -> int:
        total = 0
        while self.depth[u] > self.depth[v]:
            total += self.val[u]; u = self.parent[u]
        while self.depth[v] > self.depth[u]:
            total += self.val[v]; v = self.parent[v]
        while u != v:
            total += self.val[u] + self.val[v]
            u = self.parent[u]; v = self.parent[v]
        total += self.val[u]   # LCA once
        return total

