import java.util.*;

class HLD {
    private final int n;
    private final List<List<Integer>> adj;
    private final int[] parent, depth, heavy, size, head, pos;
    private final long[] baseVal;     // value at each pos
    private final long[] seg;         // segment tree over baseVal (sum)
    private int timer = 0;

    HLD(int n, int root, int[][] edges, long[] values) {
        this.n = n;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        parent = new int[n]; depth = new int[n]; heavy = new int[n];
        size = new int[n]; head = new int[n]; pos = new int[n];
        baseVal = new long[n]; seg = new long[4 * n];
        Arrays.fill(heavy, -1);

        dfsSize(root);
        decompose(root, root);
        for (int v = 0; v < n; v++) baseVal[pos[v]] = values[v];
        build(1, 0, n - 1);
    }

    // DFS 1: subtree sizes + heavy child (iterative post-order).
    private void dfsSize(int root) {
        Deque<Integer> st = new ArrayDeque<>();
        int[] order = new int[n]; int idx = 0;
        boolean[] seen = new boolean[n];
        st.push(root); parent[root] = root; seen[root] = true;
        while (!st.isEmpty()) {
            int node = st.pop(); order[idx++] = node;
            for (int nx : adj.get(node)) if (!seen[nx]) {
                seen[nx] = true; parent[nx] = node; depth[nx] = depth[node] + 1; st.push(nx);
            }
        }
        for (int i = n - 1; i >= 0; i--) {   // children before parents
            int node = order[i];
            size[node] = 1;
            int best = -1, bestSize = 0;
            for (int c : adj.get(node)) if (c != parent[node]) {
                size[node] += size[c];
                if (size[c] > bestSize) { bestSize = size[c]; best = c; }
            }
            heavy[node] = best;
        }
    }

    // DFS 2: assign pos along chains, heavy child first (iterative).
    private void decompose(int root, int h) {
        Deque<int[]> st = new ArrayDeque<>();   // {node, chainHead}
        st.push(new int[]{root, h});
        while (!st.isEmpty()) {
            int[] top = st.pop();
            int node = top[0], chainHead = top[1];
            head[node] = chainHead;
            pos[node] = timer++;
            // Push light children first so the heavy child is processed next (LIFO).
            for (int c : adj.get(node)) {
                if (c != parent[node] && c != heavy[node]) st.push(new int[]{c, c});
            }
            if (heavy[node] != -1) st.push(new int[]{heavy[node], chainHead});
        }
    }

    private void build(int node, int lo, int hi) {
        if (lo == hi) { seg[node] = baseVal[lo]; return; }
        int mid = (lo + hi) >>> 1;
        build(2 * node, lo, mid); build(2 * node + 1, mid + 1, hi);
        seg[node] = seg[2 * node] + seg[2 * node + 1];
    }

    private void segUpdate(int node, int lo, int hi, int i, long v) {
        if (lo == hi) { seg[node] = v; return; }
        int mid = (lo + hi) >>> 1;
        if (i <= mid) segUpdate(2 * node, lo, mid, i, v);
        else segUpdate(2 * node + 1, mid + 1, hi, i, v);
        seg[node] = seg[2 * node] + seg[2 * node + 1];
    }

    private long segQuery(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return seg[node];
        int mid = (lo + hi) >>> 1;
        return segQuery(2 * node, lo, mid, l, r) + segQuery(2 * node + 1, mid + 1, hi, l, r);
    }

    void update(int node, long v) {
        segUpdate(1, 0, n - 1, pos[node], v);
    }

    long pathQuery(int u, int v) {
        long res = 0;
        while (head[u] != head[v]) {                 // O(log n) chain hops
            if (depth[head[u]] < depth[head[v]]) { int t = u; u = v; v = t; }
            res += segQuery(1, 0, n - 1, pos[head[u]], pos[u]);
            u = parent[head[u]];
        }
        if (depth[u] > depth[v]) { int t = u; u = v; v = t; }
        res += segQuery(1, 0, n - 1, pos[u], pos[v]);  // final same-chain range
        return res;
    }
}

